  const spin = new THREE.Quaternion(), axis = new THREE.Vector3();
  const tiltQ = new THREE.Quaternion(), xAxis = new THREE.Vector3(1, 0, 0);
  const back = new THREE.Vector3();

  const place = (time: number) => {
    defs.forEach((d, i) => {
      const f = course.sample(d.s);
      let scale = 1;
      if (collected[i]) {
