      s: +pick.r.s.toFixed(3), lat: +pick.r.lat.toFixed(3), h: +pick.r.h.toFixed(3), above_water: +(pick.r.h - WATER - R0 * pick.scale).toFixed(3), along: +pick.r.along.toFixed(3) });
